#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_reverse_basic() { assert_eq!(reverse_string("hello"), "olleh"); }
    #[test]
    fn test_reverse_empty() { assert_eq!(reverse_string(""), ""); }
